<script setup lang="ts">import{ref}from'vue';import{api}from'../../api';const selected=ref<any[]>([]),items=ref([{id:'content-1',author:'姜姜',title:'今日直播预告',kind:'动态',status:'PENDING_REVIEW'}]);async function batch(status:'APPROVED'|'REJECTED'){if(!selected.value.length)return;await api.post('/moderation/content/batch',{ids:selected.value.map(x=>x.id),status,reason:status==='REJECTED'?'不符合发布规范':undefined});items.value=[]}</script><template><section class="page"><h1 class="page-title">内容审核</h1><div class="toolbar"><el-button type="success" @click="batch('APPROVED')">批量通过</el-button><el-button type="danger" @click="batch('REJECTED')">批量驳回</el-button></div><el-table :data="items" @selection-change="selected=$event"><el-table-column type="selection"/><el-table-column prop="author" label="作者"/><el-table-column prop="title" label="标题"/><el-table-column prop="kind" label="类型"/><el-table-column prop="status" label="状态"/></el-table></section></template>
